Rules.InvariantScript:
ClearCollect(colDGOptions, {Value: "All"});
Collect(colDGOptions, Choices(AVCentralDepositRequests.DG));
Set(
    varUserRole,
    If( 
        !IsEmpty(
            Filter(
                RolesPermissionsList,
                Role.Value = "ADMINISTRATOR",
                UserEmail.Email = User().Email
            )
        ),
        "ADMINISTRATOR",
        "USER"
    )
);



//ClearCollect(colAssignees, {Value: "All"});
ForAll(
    Distinct(Filter(RolesPermissionsList, Role.Value = "ADMINISTRATOR"), UserEmail.DisplayName),
    Collect(colAssignees, {Value: ThisRecord.Value})
);

Set(varFilter, Coalesce(varNavFilter, "All"));
Set(varNavFilter, Blank());
Set(varFilterDG, "");
Set(varFilterRequestName, "");
Set(varFilterStartDate, Blank());
Set(varFilterEndDate, Blank());
ClearCollect(colMyReqs, AVCentralDepositRequests);
ClearCollect(colMyMedia, AVCentralDepositMediaItems);
If(
    CountRows(colMyReqs) >= 2000 Or CountRows(colMyMedia) >= 2000,
    Notify(
        "Only the first 2000 requests are loaded, so older ones may be missing. Narrow your search - status, production type, date range, ID or title - to work with a smaller set.",
        NotificationType.Warning
    )
);
UpdateContext({locProdTypeFilter: Blank()});

